+			}
+		}
+	case "brain_changes":
+		err = runSemanticChanges(ctx, cmd, opts, semanticChangesOptions{limit: limit, json: true})
+	default:
+		err = fmt.Errorf("unknown tool: %s", params.Name)
+	}
+	if err != nil {
+		return nil, err
+	}
